        [82889286] = 'Die Seraphim beschwört den Zorn eines Erzengels, der das bezeichnete Ziel trifft und oft schwere Verletzungen verursacht.',
        [82889511] = 'Mit diesem Zauberspruch vergrößert die Seraphim ihr Blickfeld. Die Intensität dieses Lichts fügt umliegenden Gegnern leichten Schaden zu.',
        [82915161] = 'Die Fähigkeit der Wendigkeit erhöht die eigene Angriffsfähigkeit im Kampf und macht es leichter, Gegner mit Waffen zu treffen.',
        [82915162] = 'Die Fähigkeit des Parierens erhöht die eigene Verteidigungsfähigkeit im Kampf und macht es leichter, feindlichen Waffenangriffen auszuweichen. Die Verteidigungsfähigkeit wird durch den Einsatz von Schilden verbessert.',
        [82927365] = 'Erhöht die Chance, einen Gegner mit Waffen zu treffen.',
        [82927366] = 'Erhöht die Chance, gegnerischen Waffenangriffen auszuweichen. Beim Einsatz eines Schildes wird die Chance weiter erhöht.',
        [82953131] = 'Beschwört einen Wolf zur Unterstützung im Kampf. Dieser Wolf verursacht physischen Schaden und magischen Schaden.',
        [82953235] = 'Beschwört einen Wolf zur Unterstützung im Kampf. Dieser Wolf verursacht Feuer und Giftschaden.',
        [82953243] = 'Beschwört Fledermäuse, die alle Feinde angreifen und die Gesundheit des Helden wiederherstellen. Diese Fledermäuse richten physischen Schaden und Feuerschaden an.',
        [82953244] = 'Beschwört Fledermäuse, die alle Feinde angreifen und entwaffnen können. Diese Fledermäuse richten magischen Schaden und Giftschaden an.',
        [82953348] = 'Beschwört Fledermäuse, die anstelle des Helden Schaden nehmen. Diese Fledermäuse richten physischen Schaden und Giftschaden an.',
        [82965673] = 'Beschwört ein Einhorn, das an der Seite der Waldelfe kämpft. Das Einhorn fügt physischen und magischen Schaden zu.',
        [82965900] = 'Verursacht schweren Schaden beim Gegner.',
        [82966125] = 'Erhöht den Lichtradius und schädigt umliegende Gegner.',
        [82979225] = '<colorl=FFFFFFFF80>Kampfkünste kaufen',
        [82979227] = '<colorw=FFFFFFFF80>Kaufe eine <colorw=FFFFFFFF80>Kampfkunst Rune<n>Erhöht die Kampfkunst um 1 Punkt.',
        [82979230] = 'Klicke hier, um eine <colorw=FFFFFFFF80>Kampfkunst zu kaufen und erhöhe damit die Stufe um <colorw=FFFFFFFF80>1.',
        [82979231] = 'Verwende die Pfeile, um die <colorw=FFFFFF80>Kampfkunst auszuwählen, die hochgestuft werden soll.<n>Je höher die <colorw=FFFFFF80>Kampfkunststufe, desto höher ist der <colorw=FFFFFF80>Kaufpreis der nächsten Stufe.<n>Der <colorw=FFFFFF80>Kaufpreis wird auf der rechten Seite angezeigt. Die aktuelle <colorw=FFFFFF80>Kampfkunststufe wird oben angezeigt.',
        [236931057] = 'Erhöht Gesundheit und Regeneration, den physischen Widerstand und reduziert die Abklingzeit der Kampfkünste.',
        [430560712] = 'Erhöht Gesundheit, Angriff und leicht die Verteidigung, sowie physischen Schaden und Feuerschaden von Waffen und Kampfkünsten.',
        [594737219] = 'Erhöht Verteidigung und leicht den Angriff, physischen Schaden im Fernkampf, Feuerresistenz und Feuerschaden von Waffen und Kampfkünsten.',
